extension Tokens {
    /// A colour in light and dark appearances, as 0xRRGGBBAA in sRGB, and the one dynamic `NSColor`
    /// that shows whichever the view is drawn in.
    struct Swatch {
        /// The colour in a light appearance.
        let light: UInt32
        /// The colour in a dark appearance.
        let dark: UInt32
        /// The colour as AppKit draws it: `light` or `dark`, by the appearance it is drawn in.
        let nsColor: NSColor

        /// A colour that is the same in both appearances.
        init(_ both: UInt32) {
            self.init(light: both, dark: both)
        }

        init(light: UInt32, dark: UInt32) {
            self.light = light
            self.dark = dark
            nsColor = NSColor(name: nil) { appearance in
                let isDark = appearance.bestMatch(from: [.aqua, .darkAqua]) == .darkAqua
                return Swatch.srgb(isDark ? dark : light)
            }
        }

        /// The colour for SwiftUI, following the appearance as `nsColor` does.
        var color: Color { Color(nsColor: nsColor) }

        /// An sRGB colour from 0xRRGGBBAA.
        static func srgb(_ rgba: UInt32) -> NSColor {
            let channel = { (shift: UInt32) in CGFloat((rgba >> shift) & 0xFF) / 255 }
            let (red, green, blue) = (channel(24), channel(16), channel(8))
            return NSColor(srgbRed: red, green: green, blue: blue, alpha: channel(0))
        }
    }

    /// A text style: its size and line height, its weight, and whether it is a title.
    struct TextStyle: Equatable {
        let size: CGFloat
        let lineHeight: CGFloat
        let weight: Font.Weight
        /// Titles are set in the display face, everything else in the text face.
        let display: Bool

        init(size: CGFloat, lineHeight: CGFloat, weight: Font.Weight, display: Bool = false) {
            self.size = size
            self.lineHeight = lineHeight
            self.weight = weight
            self.display = display
        }

        /// The system font at this size and weight. SF Pro picks its text or display cut by size,
        /// so the system font is both faces.
        var font: Font { .system(size: size, weight: weight) }
    }
}

